import os
for k in ['OMP_NUM_THREADS','OPENBLAS_NUM_THREADS','MKL_NUM_THREADS']:os.environ[k]='1'
import pathlib,pandas as pd,numpy as np,sqlite3,json,datetime
P=pathlib.Path.cwd();B=P/'results/mp10_hypothesis_followup_v2';T=B/'tables';reg=pd.read_csv(T/'model_registry.tsv',sep='\t');reg['primary']=(reg.setting.eq('main')&reg['mask'].eq('Full')&((reg.state.eq('H05')&reg.kind.isin(['paired_score','gsea','direct_D','scenic_activity']))|reg.kind.eq('cross')));reg['analysis_role']=np.where(reg.primary,'v2_primary','v2_sensitivity');reg.loc[reg.kind.eq('cross')&reg.FDR_family.str.startswith('EC_'),'analysis_role']='v2_exploratory';reg.loc[reg.kind.eq('cross')&reg.FDR_family.str.startswith('Treg_secondary'),'analysis_role']='v2_secondary';reg.loc[reg.kind.eq('direct_D')&reg.x.eq('BLOCH'),'analysis_role']='v2_downstream_supplement';reg.loc[reg.model_id.str.startswith('V2M_'),'primary']=False;reg.loc[reg.model_id.str.startswith('V2M_'),'analysis_role']='v2_M2_diagnostic';reg.to_csv(T/'model_registry.tsv',sep='\t',index=False)
for f in ['score_model_results.tsv.gz','gsea_model_results.tsv.gz']:
 d=pd.read_csv(T/f,sep='\t');d=d.drop(columns=['primary','analysis_role'],errors='ignore').merge(reg[['model_id','primary','analysis_role']],on='model_id',validate='1:1');d.to_csv(T/f,sep='\t',index=False)
(B/'config/technical_revision_03.json').write_text(json.dumps(dict(time=datetime.datetime.now(datetime.timezone.utc).isoformat(),reason='Correct v2 primary display flag: H10/H50 main settings are sensitivity to H05, not v2 primary. No coefficients, samples, P or FDR families changed. EC/secondary/downstream roles explicit.'),indent=2))
c=sqlite3.connect('file:/refdir/Rlib/org.Hs.eg.db/extdata/org.Hs.eg.sqlite?mode=ro',uri=True);info=pd.read_sql('select i.symbol,i.gene_name,t.gene_type from gene_info i left join genetype t on i._id=t._id',c).drop_duplicates('symbol');g=pd.read_csv(T/'official_gene_sets.tsv.gz',sep='\t');g=g.merge(info,left_on='gene',right_on='symbol',how='left');g['annotation_status']=np.where(g.gene_type.notna(),'annotated_NCBI_2025Sep24','not_resolved_in_installed_annotation');g.to_csv(T/'official_gene_biotypes.tsv.gz',sep='\t',index=False)
old=pd.read_csv(P/'results/mp10_hypothesis_followup_v1/tables/signature_registry.tsv',sep='\t');old=old[old.signature.isin(['STEROL_SYNTH','FA_SYNTH_DESAT','LIPID_UPTAKE_TRANSPORT','PRENYLATION'])];old['panel_provenance_class']=old.signature.map({'STEROL_SYNTH':'Reactome-derived historical panel','FA_SYNTH_DESAT':'curated literature panel, not official set','LIPID_UPTAKE_TRANSPORT':'multi-source combined panel, not official set','PRENYLATION':'curated panel, not official set'});old.to_csv(T/'legacy_panel_provenance.tsv',sep='\t',index=False)
cc=pd.read_csv(T/'EC_gene_count_concentration.tsv.gz',sep='\t');cc.loc[cc.raw_counts.eq(0),'flagged_cell_count_share']=np.nan;cc.to_csv(T/'EC_gene_count_concentration.tsv.gz',sep='\t',index=False);le=pd.read_csv(T/'mTORC1_leading_edge_classification.tsv.gz',sep='\t');le=set(le.loc[le.source_model.eq('M0073'),'gene']);main=pd.read_csv(T/'mTORC1_M0073_membership.tsv',sep='\t');x=cc[cc.gene.isin(le)&cc.sample_uid.isin(main.sample_uid)].merge(main[['sample_uid','dataset']],on='sample_uid');x.to_csv(T/'EC_mTORC1_LE_cell_concentration.tsv.gz',sep='\t',index=False)
y=x.groupby('sample_uid').agg(n_LE_genes=('gene','size'),n_LE_genes_detected=('detected_cells',lambda a:(a>0).sum()),median_detected_fraction=('detected_fraction','median'),median_top1pct_share=('top1pct_count_share','median'),median_top5pct_share=('top5pct_count_share','median'),median_epi_flag_share=('flagged_cell_count_share','median'));y.reset_index().to_csv(T/'EC_mTORC1_LE_concentration_summary.tsv',sep='\t',index=False)
print('Annotation/provenance summaries completed')
